"""Universal C99 Backend for R2-IR.
Emits freestanding, MISRA-compliant C code preserving domain barriers and 64-bit address safety.
"""

from typing import Dict, List, Set
from src.lowering.ir import (
    IRModule, IRFunction, BasicBlock, Instruction,
    Assign, BinOp, UnOp, RamLoad, RamStore, MmioLoad, MmioStore,
    MmioBarrier, Call, Jump, BranchIf, Return, Assert, Reg, Const, Operand
)

class C99Emitter:
    def __init__(self):
        pass

    def emit_module(self, mod: IRModule) -> str:
        lines = [
            "/* Auto-generated by R2 Compiler (r2c) - C99 Backend */",
            "#include <stdint.h>",
            "#include <stdbool.h>",
            "#include <stddef.h>",
            "#include <string.h>",
            "",
            "/* Memory Barrier Invariants */",
            "#if defined(__GNUC__) || defined(__clang__)",
            "  #define R2_BARRIER() __asm__ __volatile__(\"\" ::: \"memory\")",
            "  #define R2_DMB()     __sync_synchronize()",
            "#else",
            "  #define R2_BARRIER() ((void)0)",
            "  #define R2_DMB()     ((void)0)",
            "#endif",
            "",
            "/* Type definitions & Constants */",
            "typedef enum {",
            "    Status_Ok = 0,",
            "    Status_AuthFailed = 1,",
            "    Status_MonotonicViolation = 2,",
            "    Status_CrcMismatch = 3",
            "} Status;",
            "",
            "#define PB_MAGIC 0x50423031U",
            "#define SLOT_SIZE 4096U",
            "#define HEADER_A_OFFSET 0x0000U",
            "#define HEADER_B_OFFSET 0x1000U",
            ""
        ]

        # Forward declarations with uintptr_t for 64-bit address safety
        for fn in mod.functions:
            param_list = [f"uintptr_t {p.name}" for p in fn.params]
            lines.append(f"uint32_t {fn.name}({', '.join(param_list)});")
        lines.append("")

        for fn in mod.functions:
            lines.append(self.emit_function(fn))
            lines.append("")

        return "\n".join(lines)

    def emit_function(self, fn: IRFunction) -> str:
        param_list = [f"uintptr_t {p.name}" for p in fn.params]
        proto = f"uint32_t {fn.name}({', '.join(param_list)})"
        
        lines = [proto + " {"]
        stack_arrays = getattr(fn, "stack_arrays", {})
        for name, size in stack_arrays.items():
            lines.append(f"    uint8_t stack_{name}[{size}];")
            lines.append(f"    memset(stack_{name}, 0, {size});")
        
        # Collect all virtual registers
        registers: Set[str] = set()
        param_names = {p.name for p in fn.params}

        for bb in fn.blocks:
            for inst in bb.instructions:
                if hasattr(inst, "dest") and isinstance(inst.dest, Reg):
                    registers.add(inst.dest.name)
                for field_name in ("src", "left", "right", "addr", "cond", "val"):
                    val = getattr(inst, field_name, None)
                    if isinstance(val, Reg):
                        registers.add(val.name)
                if hasattr(inst, "args"):
                    for a in inst.args:
                        if isinstance(a, Reg):
                            registers.add(a.name)

        stack_names = {f"stack_{name}" for name in stack_arrays.keys()}
        local_registers = sorted(registers - param_names - stack_names)
        for reg in local_registers:
            # Use uintptr_t for registers to store both 32-bit values and 64-bit pointers cleanly
            lines.append(f"    uintptr_t {reg} = 0;")
        if local_registers:
            lines.append("")

        for bb in fn.blocks:
            lines.append(f"{bb.label}:")
            for inst in bb.instructions:
                code = self._emit_inst(inst)
                if code:
                    lines.append(f"    {code};")

        lines.append("}")
        return "\n".join(lines)

    def _fmt_op(self, op: Operand) -> str:
        if op is None:
            return "0ULL"
        if isinstance(op, Reg):
            return op.name
        elif isinstance(op, Const):
            if op.value is None or str(op.value) == "None":
                return "0ULL"
            return f"0x{op.value:X}ULL" if isinstance(op.value, int) and op.value > 9 else f"{op.value}ULL"
        if str(op) == "None":
            return "0ULL"
        return str(op)

    def _emit_inst(self, inst: Instruction) -> str:
        if isinstance(inst, Assign):
            return f"{inst.dest.name} = (uintptr_t)({self._fmt_op(inst.src)})"
        elif isinstance(inst, BinOp):
            return f"{inst.dest.name} = (uintptr_t)({self._fmt_op(inst.left)} {inst.op} {self._fmt_op(inst.right)})"
        elif isinstance(inst, UnOp):
            if inst.op == "&":
                return f"{inst.dest.name} = (uintptr_t)(&({self._fmt_op(inst.src)}))"
            return f"{inst.dest.name} = (uintptr_t)({inst.op}({self._fmt_op(inst.src)}))"
        elif isinstance(inst, RamLoad):
            addr_calc = f"((const uint8_t*)((uintptr_t)({self._fmt_op(inst.addr)})) + {inst.offset})"
            if "val" in inst.dest.name or "byte" in inst.dest.name:
                return f"{inst.dest.name} = (uintptr_t)(*((volatile const uint8_t*){addr_calc}))"
            if "base" in inst.dest.name or "addr" in inst.dest.name or "slot" in inst.dest.name:
                return f"{inst.dest.name} = (uintptr_t)(*((volatile const uintptr_t*)(const void*){addr_calc}))"
            return f"{inst.dest.name} = (uintptr_t)(*((volatile const uint32_t*)(const void*){addr_calc}))"
        elif isinstance(inst, RamStore):
            return f"*((volatile uint32_t*)({self._fmt_op(inst.addr)} + {inst.offset})) = (uint32_t)({self._fmt_op(inst.src)})"
        elif isinstance(inst, MmioLoad):
            addr_calc = f"((const uint8_t*)((uintptr_t)({self._fmt_op(inst.addr)})) + {inst.offset})"
            if "base" in inst.dest.name or "addr" in inst.dest.name or "slot" in inst.dest.name:
                return f"{inst.dest.name} = (uintptr_t)(*((volatile const uintptr_t*)(const void*){addr_calc}))"
            return f"{inst.dest.name} = (uintptr_t)(*((volatile const uint32_t*)(const void*){addr_calc}))"
        elif isinstance(inst, MmioStore):
            return f"*((volatile uint32_t*)({self._fmt_op(inst.addr)} + {inst.offset})) = (uint32_t)({self._fmt_op(inst.src)})"
        elif isinstance(inst, MmioBarrier):
            return "R2_DMB()"
        elif isinstance(inst, Call):
            args_str = ", ".join(f"(uintptr_t)({self._fmt_op(a)})" for a in inst.args)
            if inst.dest is None:
                return f"{inst.callee}({args_str})"
            return f"{self._fmt_op(inst.dest)} = (uintptr_t)({inst.callee}({args_str}))"
        elif isinstance(inst, Jump):
            return f"goto {inst.target}"
        elif isinstance(inst, BranchIf):
            return f"if ({self._fmt_op(inst.cond)}) {{ goto {inst.true_target}; }} else {{ goto {inst.false_target}; }}"
        elif isinstance(inst, Return):
            if inst.val is not None:
                return f"return (uint32_t)({self._fmt_op(inst.val)})"
            return "return 0"
        elif isinstance(inst, Assert):
            return f"/* assert {self._fmt_op(inst.cond)} */"
        return ""
